export const handleError = (
  e: any,
  description: string | null | any[] = null,
  callback: (() => void) | null = null,
) => {
  process.env.NODE_ENV === 'development' && console.error(e)
  let message = description || 'Oops! Something went wrong.'
  if (e && !description) {
    if (e.response) {
      message = e.response.message
    } else if (e.message) {
      message = e.message
    }
  }
  standaloneToast({
    title: 'Error',
    description: message,
    status: 'error',
    duration: 10000,
    isClosable: true,
  })
  if (callback) callback()
}

